$k$ & $V(k)$ (bits) & $\Delta(k-1)$ \\
\midrule
0 & $0$ & --- \\
1 & $0.52$ & $0.52$ \\
2 & $2.43$ & $1.91$ \\
3 & $3.19$ & $0.76$ \\
\bottomrule
\end{tabular}
\caption{Reported hint values.}\label{tab:data}
\end{table}

On the window the curve is superadditive: $V(1)+V(1)=1.04<2.43$ and $V(1)+V(2)=2.95<3.19$.
Its last gain is smaller than the previous one. The question is whether these two
properties can hold for all $k$.

\emph{Contributions.} (1) Precise definitions (Section~\ref{sec:defs}). (2) A calculus of
compounding and diminishing curves (Section~\ref{sec:calc}). (3) An analysis of the data
that quantifies over \emph{all} curves through the four points (Section~\ref{sec:data}).
(4) A bridge to the factor-residue model (Section~\ref{sec:model}).

\section{Definitions}\label{sec:defs}

Throughout, $V:\N\to\R$ is arbitrary.

\begin{definition}[Marginal gain]
$\Delta(k)=V(k+1)-V(k)$.
\end{definition}

\begin{definition}[Compounding]
$V$ is \emph{compounding} if $V(m)+V(n)\le V(m+n)$ for all $m,n\in\N$.
\end{definition}

\begin{definition}[Diminishing returns from $a$]
$V$ has \emph{diminishing returns from $a$} if $\Delta(k+1)\le\Delta(k)$ for all $k\ge a$.
\end{definition}

\begin{definition}[Matching the data]
$V$ \emph{matches the data} if $V(0)=0$, $V(1)=0.52$, $V(2)=2.43$, $V(3)=3.19$.
\end{definition}

\section{The scaling calculus}\label{sec:calc}

\begin{lemma}[Propagation]\label{lem:prop}
If $V$ has diminishing returns from $a$ and $k\ge a$, then $\Delta(k+j)\le\Delta(k)$ for
all $j\ge0$.
\end{lemma}
\begin{proof}
Induction on $j$, using $\Delta(k+j+1)\le\Delta(k+j)$.
\end{proof}

\begin{lemma}[Tangent cap]\label{lem:cap}
If $V$ has diminishing returns from $a$ and $k\ge a$, then
$V(k+j)\le V(k)+j\,\Delta(k)$ for all $j\ge0$.
\end{lemma}
\begin{proof}
$V(k+j+1)=V(k+j)+\Delta(k+j)\le V(k)+j\Delta(k)+\Delta(k)$ by induction and
Lemma~\ref{lem:prop}.
\end{proof}

\begin{lemma}\label{lem:zero}
If $V$ compounds then $V(0)\le0$.
\end{lemma}
\begin{proof}
$2V(0)\le V(0)$.
\end{proof}

\begin{lemma}[Secant floor]\label{lem:floor}
If $V$ compounds then $(m+1)V(b)\le V((m+1)b)$ for all $b,m\in\N$.
\end{lemma}
\begin{proof}
Induction: $V((m+2)b)\ge V((m+1)b)+V(b)\ge(m+2)V(b)$.
\end{proof}

\begin{theorem}[Compounding Horizon]\label{thm:horizon}
If $V$ compounds and has diminishing returns from $a$, then for all $k\ge a$ and all
$b\in\N$,
\[ V(b)\le b\,\Delta(k). \]
Hence every marginal gain from $a$ on is at least $\sup_{b\ge1}V(b)/b$.
\end{theorem}
\begin{proof}
For $b=0$ use Lemma~\ref{lem:zero}. Let $b\ge1$ and suppose $c:=V(b)-b\Delta(k)>0$. Pick
$N\in\N$ with $Nc>V(k)-k\Delta(k)$ and set $M=k+N$, so $(M+1)b>k$. By
Lemma~\ref{lem:floor}, $(M+1)V(b)\le V((M+1)b)$. By Lemma~\ref{lem:cap} with
$j=(M+1)b-k$, $V((M+1)b)\le V(k)+((M+1)b-k)\Delta(k)$. Hence
$(M+1)c\le V(k)-k\Delta(k)<Nc\le(M+1)c$, a contradiction.
\end{proof}

\begin{remark}
Compounding pushes the curve up at average slope $V(b)/b$ along multiples of $b$.
Diminishing returns holds it under a line of slope $\Delta(k)$. The argument has the same
flavour as Fekete's lemma.
\end{remark}

\begin{theorem}[Compounding plus concavity is linearity]\label{thm:linear}
If $V$ compounds, has diminishing returns from $0$, and $V(0)=0$, then $V(k)=kV(1)$ for
all $k$.
\end{theorem}
\begin{proof}
Lemma~\ref{lem:cap} at $k=0$ gives $V(k)\le kV(1)$. Lemma~\ref{lem:floor} with $b=1$
gives $V(k)\ge kV(1)$ for $k\ge1$.
\end{proof}

\begin{corollary}
Under the hypotheses of Theorem~\ref{thm:linear}, $\Delta(k)=V(1)$ for all $k$, and there
is no $k$ with $\Delta(k+1)<\Delta(k)$. Compounding and strictly diminishing returns are
incompatible.
\end{corollary}

\begin{theorem}[Affine ceiling collapse]\label{thm:affine}
If $V$ compounds and $V(k)\le ck+b$ for all $k$, then $V(a)\le ca$ for all $a$.
\end{theorem}
\begin{proof}
If $e:=V(a)-ca>0$, choose $N$ with $Ne>b$. Then
$(N+1)V(a)\le V((N+1)a)\le c(N+1)a+b$, so $(N+1)e\le b<Ne$.
\end{proof}

\begin{corollary}[Bounded collapse]\label{cor:bounded}
If $V$ compounds and $V(k)\le B$ for all $k$, then $V(a)\le0$ for all $a$.
\end{corollary}

\section{Analysis of the reported curve}\label{sec:data}

In this section $V$ is \emph{any} curve matching the data.

\begin{proposition}[Shape]
$\Delta(0)=0.52$, $\Delta(1)=1.91$, $\Delta(2)=0.76$. All are positive,
$\Delta(0)<\Delta(1)$ and $\Delta(2)<\Delta(1)$, so the curve is S-shaped. In particular
$V$ does not have diminishing returns from $0$. On the window $V$ is strictly
superadditive: $V(1)+V(1)<V(2)$ and $V(1)+V(2)<V(3)$.
\end{proposition}

\begin{theorem}[Asymptotic slope]\label{thm:slope}
If $V$ compounds and has diminishing returns from $a$, then $\Delta(k)\ge1.215$ for all
$k\ge a$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:horizon} with $b=2$: $2.43\le2\Delta(k)$.
\end{proof}

\begin{theorem}[The verdict cannot hold as a law]
No curve matching the data both compounds and has diminishing returns from $k=2$ on.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:slope} at $k=2$ gives $0.76\ge1.215$.
\end{proof}

\begin{theorem}[Sharp failure at $k=4$]
The inequalities $V(2)+V(2)\le V(4)$ and $\Delta(3)\le\Delta(2)$ are incompatible: the
first forces $V(4)\ge4.86$, the second $V(4)\le3.95$.
\end{theorem}

\begin{proposition}
If $V$ compounds, then for no $b$ is $V(k)\le k+b$ for all $k$ (Theorem~\ref{thm:affine}
would give $2.43\le2$). If $V(k)\le B$ for all $k$, then $V$ does not compound
(Corollary~\ref{cor:bounded} would give $0.52\le0$).
\end{proposition}

\begin{proposition}[Each half alone is consistent]
The curve $D$ with $D(0)=0$, $D(1)=0.52$, $D(k)=2.43+0.76(k-2)$ for $k\ge2$ matches the
data and has diminishing returns from $1$. The curve $C$ that agrees with the data on
$\{0,1,2,3\}$ and has $C(k)=k^2$ for $k\ge4$ matches the data and compounds.
\end{proposition}
\begin{proof}[Proof sketch]
For $D$ the gains are $0.52,1.91,0.76,0.76,\dots$. For $C$, note $C(k)\le k^2$ for all
$k$. If $m+n\ge4$ then $C(m)+C(n)\le m^2+n^2\le(m+n)^2=C(m+n)$. The finitely many cases
with $m+n\le3$ are checked directly.
\end{proof}

\section{The factor-residue model}\label{sec:model}

Let $\Omega$ be a finite nonempty population with the uniform distribution, $L:\Omega\to
\Lambda$ a label, and $P,Q:\Omega\to R$ residues in a finite commutative ring with $2$
invertible. Write $I(L;f)$ for mutual information in bits and $H(L)$ for the label
entropy. We use $0\le I(L;f)\le H(L)$ and the fact that $I(L;f)$ depends only on the
partition of $\Omega$ into fibres of $f$. The views are: the \emph{product view} $PQ$;
the \emph{sum dial}, which adds $P+Q$ (the gap dial $P-Q$ is symmetric); and the
\emph{joint residue view} $\rho$, whose fibres are those of $(P,Q)$. Set
$\HV=I(L;\rho)-I(L;PQ)$, and let $\SH$ be the conditional gain of the sum dial over the
product view. Then $0\le\SH\le\HV\le H(L)$.

\begin{definition}
The \emph{factor-residue hint curve} is $W(0)=0$, $W(1)=\SH$, $W(k)=\HV$ for $k\ge2$.
\end{definition}

\begin{theorem}[Third-hint saturation]
For any $h:R\times R\to\beta$,
$I(L;(\rho,h(P,Q)))=I(L;\rho)$.
\end{theorem}
\begin{proof}
Both views have the same fibres.
\end{proof}

\begin{proposition}
$W$ is monotone, has diminishing returns from $1$, and satisfies $W(k)\le H(L)$.
\end{proposition}

\begin{theorem}[Compounding iff zero]
$W$ compounds if and only if $W\equiv0$.
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:bounded}, $W\le0$, while monotonicity gives $W\ge W(0)=0$.
\end{proof}

Since $2$ is invertible, $(P+Q,PQ)$ determines $\{P,Q\}$ as the roots of
$X^2-(P+Q)X+PQ$. Only an orientation remains. A \emph{sign selector} $s:R\to F$ recovers
the orientation from the difference $P-Q$, and we use the following chain-rule bound.

\begin{proposition}[Sign-selector ceiling]
For any sign selector $s:R\to F$, $\HV\le\SH+\log_2|F|$.
\end{proposition}

Over $\mathbb Z/p\mathbb Z$ with $p$ an odd prime, $|F|=2$: this is the one-orientation-bit
law. Over $\prod_{i<k}\mathbb Z/p_i\mathbb Z$ the coordinatewise selectors give
$|F|=2^k$.

\begin{theorem}[One field cannot carry the jump]
Over $\mathbb Z/p\mathbb Z$ with $p$ an odd prime, no battery has $\SH=0.52$ and
$\HV=2.43$, since $2.43>0.52+1$. The same holds with the gap hint.
\end{theorem}

\begin{theorem}[One bit per field]
Over $\prod_{i<k}\mathbb Z/p_i\mathbb Z$ with odd primes $p_i$, $\HV-\SH\le k$.
\end{theorem}

\section{Algorithms}

\begin{algorithm}[Verdict audit]
Given $V(0),\dots,V(n)$ and an onset $a$: compute $\Delta$. Compute the locked-in rate
$r=\max_{1\le b\le n}V(b)/b$. Refute ``compounding plus diminishing from $a$'' if some
observed $\Delta(k)<r$ with $k\ge a$. Then search for the first $N>n$ where the
compounding lower bound $\max_{m+m'=N}(V(m)+V(m'))$ exceeds the tangent bound
$V(n)+(N-n)\Delta(n-1)$. On the data, $r=1.215>0.76$, and the search stops at $N=4$.
\end{algorithm}

\begin{algorithm}[Field-count bound]
The number of odd prime fields satisfies $k\ge\lceil\HV-\SH\rceil$. On the data,
$k\ge2$.
\end{algorithm}

\section{Discussion and future work}

On its window the curve does compound and its last gain does diminish. As a law, the
verdict contradicts itself, and the contradiction appears at the next measurement with a
margin of $0.91$ bits. The data alone cannot decide which half to drop. Boundedness by an
entropy rules out compounding, and in the residue model diminishing returns is forced. We
propose the replacement verdict \emph{hints compound locally, saturate globally}. The
positive third gain and the jump larger than one bit both point beyond a single prime field
and its residues.

Open directions: (1) an inflection bound $k^*\le\lceil B/\Delta(0)\rceil$ for bounded
curves with unimodal gains; (2) exactness of the $k$-field ceiling, attained by products
of orientation batteries; (3) a construction of extra-residue third hints, for instance a
second modulus combined through the Chinese remainder theorem; (4) quantitative,
finite-horizon versions of the Compounding Horizon Theorem.

