from fractions import Fraction
from typing import Callable, List, Optional, Tuple


def superadditivity_witness(V: Callable[[int], Fraction], N: int) -> Optional[Tuple[int, int]]:
    """Return a pair (m, n) with m + n <= N and V(m) + V(n) > V(m + n), or None. O(N^2)."""
    for m in range(N + 1):
        for n in range(m, N + 1 - m):
            if V(m) + V(n) > V(m + n):
                return (m, n)
    return None


def diminishing_witness(V: Callable[[int], Fraction], a: int, N: int) -> Optional[int]:
    """Return k in [a, N-2] with Delta(k+1) > Delta(k), or None. O(N)."""
    for k in range(a, N - 1):
        if V(k + 2) - V(k + 1) > V(k + 1) - V(k):
            return k
    return None


DATA: List[Fraction] = [Fraction(0), Fraction(52, 100), Fraction(243, 100), Fraction(319, 100)]


def compounding_ext(k: int) -> Fraction:
    return DATA[k] if k < 4 else Fraction(k * k)


def diminishing_ext(k: int) -> Fraction:
    return DATA[k] if k < 2 else Fraction(243, 100) + Fraction(76, 100) * (k - 2)


if __name__ == "__main__":
    print("k^2 continuation: superadditivity witness up to 200 ->", superadditivity_witness(compounding_ext, 200))
    print("k^2 continuation: diminishing-from-2 witness       ->", diminishing_witness(compounding_ext, 2, 200))
    print("tangent continuation: superadditivity witness      ->", superadditivity_witness(diminishing_ext, 200))
    print("tangent continuation: diminishing-from-1 witness   ->", diminishing_witness(diminishing_ext, 1, 200))

import math
from collections import Counter
from typing import Hashable, List, Sequence, Tuple


def entropy(xs: Sequence[Hashable]) -> float:
    n = len(xs)
    return -sum(c / n * math.log2(c / n) for c in Counter(xs).values())


def mutual_information(L: Sequence[Hashable], view: Sequence[Hashable]) -> float:
    return entropy(L) + entropy(view) - entropy(list(zip(L, view)))


def min_prime_fields(sum_hint: float, hint_value: float) -> int:
    """One orientation bit per odd prime field: HV - SH <= k, hence k >= ceil(HV - SH)."""
    return max(0, math.ceil(hint_value - sum_hint - 1e-12))


def orientation_battery(primes: Sequence[int]) -> Tuple[float, float]:
    """Product-of-fields battery: residues P, Q in prod Z/p_i, label = coordinatewise orientation.

    Returns (SH, HV) where SH = I(L; PQ, P+Q) - I(L; PQ) and HV = I(L; P, Q) - I(L; PQ).
    """
    import itertools
    coords = [range(1, p) for p in primes]
    pts: List[Tuple[Tuple[int, ...], Tuple[int, ...]]] = [
        (P, Q) for P in itertools.product(*coords) for Q in itertools.product(*coords)]
    L = [tuple(a < b for a, b in zip(P, Q)) for P, Q in pts]
    prod = [tuple(a * b % p for a, b, p in zip(P, Q, primes)) for P, Q in pts]
    sd = [(pr, tuple((a + b) % p for a, b, p in zip(P, Q, primes))) for pr, (P, Q) in zip(prod, pts)]
    I0 = mutual_information(L, prod)
    return mutual_information(L, sd) - I0, mutual_information(L, pts) - I0


if __name__ == "__main__":
    print("reported data needs at least", min_prime_fields(0.52, 2.43), "odd prime fields")
    for ps in ([7], [11], [5, 7], [3, 5, 7]):
        sh, hv = orientation_battery(ps)
        print(f"fields {ps}: SH={sh:.3f} HV={hv:.3f} jump={hv - sh:.3f} <= {len(ps)}")
